"""Predictive failure detection: probability that a task FAILS or MISSES ITS DEADLINE, predicted before execution.

Data provenance (honest by design)
* None of the provided real datasets (PROMISE requirements, multilingual tickets) nor a GitHub metrics
  dataset contains agent *execution* outcomes, so they cannot supply failure labels.
* Training therefore uses a clearly labelled SYNTHETIC execution history generated by a documented
  simulator (agent skill, specialisation, workload, complexity, dependency fan-in, deadline slack).
* Every real run of the orchestrator appends a LIVE row to `execution_metrics`; once enough live rows
  exist, `prepare_failure_dataset(source="live")` retrains on real history.

Leakage control: only PRE-EXECUTION features are model inputs. Actual duration, attempts, retries and
final outcomes are excluded (enforced by `assert_no_leakage`). Train/test are split by workflow.
Probabilities are calibrated (Platt/sigmoid, fitted on held-out validation workflows) and the Brier score is reported before and after calibration.
"""
from __future__ import annotations

import json
import time
from functools import lru_cache

import joblib
import numpy as np
import pandas as pd
from sklearn.calibration import CalibratedClassifierCV
from sklearn.compose import ColumnTransformer
from sklearn.dummy import DummyClassifier
from sklearn.ensemble import RandomForestClassifier
from sklearn.linear_model import LogisticRegression
from sklearn.metrics import (
    average_precision_score,
    brier_score_loss,
    confusion_matrix,
    f1_score,
    precision_recall_curve,
    precision_score,
    recall_score,
)
from sklearn.model_selection import GridSearchCV, GroupKFold, GroupShuffleSplit
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import OneHotEncoder, StandardScaler

from app.core.config import CATEGORIES, PRIORITIES, settings

MODEL_PATH = settings.models_dir / "failure_predictor.joblib"
METRICS_PATH = settings.reports_dir / "failure_metrics.json"
CATEGORICAL = ["task_category", "task_priority", "agent_id"]
NUMERIC = ["task_complexity", "dependency_count", "estimated_duration", "current_workload", "deadline_slack"]
FEATURES = CATEGORICAL + NUMERIC
TARGETS = ["task_failed", "deadline_missed"]
POST_EXECUTION = {"actual_duration", "actual_duration_s", "attempts", "retries", "task_failed", "deadline_missed",
                  "completion_status", "qa_passed", "final_status"}
PRIO_URGENCY = {"low": 0, "medium": 1, "high": 2, "critical": 3}

try:
    from xgboost import XGBClassifier  # optional
except Exception:  # pragma: no cover
    XGBClassifier = None


def assert_no_leakage(columns) -> None:
    leaked = POST_EXECUTION & set(columns)
    if leaked:
        raise ValueError(f"post-execution columns must not be model inputs: {sorted(leaked)}")


# ------------------------------------------------------------------ data
def _simulate(n_workflows: int, seed: int) -> pd.DataFrame:
    """SYNTHETIC execution history. Ground truth is a noisy function of pre-execution factors."""
    rng = np.random.default_rng(seed)
    agents = settings.agent_pool
    rows = []
    for w in range(n_workflows):
        wid = f"SIMWF{w:05d}"
        n = int(rng.integers(6, 22))
        load = {a["name"]: 0 for a in agents}
        for i in range(n):
            cat = str(rng.choice(CATEGORIES, p=[0.4, 0.25, 0.12, 0.1, 0.13]))
            elig = [a for a in agents if cat in a["capabilities"]]
            a = elig[int(rng.integers(len(elig)))]
            complexity = int(rng.integers(1, 6))
            prio = str(rng.choice(PRIORITIES, p=[0.3, 0.35, 0.25, 0.1]))
            deps = int(min(i, rng.poisson(1.2)))
            est = round(complexity * 2.5 * float(rng.uniform(0.8, 1.2)), 2)
            workload = load[a["name"]]
            slack = float(rng.uniform(0.7, 2.6))
            specialist = a["capabilities"][0] == cat
            z = (-3.1 + 0.42 * complexity + 0.28 * workload + 0.18 * deps - 0.9 * (a["skill"] - 1)
                 - (0.5 if specialist else 0) + rng.normal(0, 0.6))
            failed = rng.random() < 1 / (1 + np.exp(-z))
            actual = est / a["skill"] * float(rng.lognormal(0, 0.3)) * (1 + 0.12 * workload) * (1.6 if failed else 1.0)
            missed = actual > est * slack
            rows.append({"workflow_id": wid, "task_id": f"T{i:02d}", "agent_id": a["name"], "task_category": cat,
                         "task_priority": prio, "task_complexity": complexity, "dependency_count": deps,
                         "estimated_duration": est, "current_workload": workload, "deadline_slack": round(slack, 3),
                         "deadline": round(est * slack, 2), "actual_duration": round(actual, 2),
                         "task_failed": int(failed), "deadline_missed": int(missed), "source": "synthetic"})
            load[a["name"]] += 1
    return pd.DataFrame(rows)


def _live_rows() -> pd.DataFrame:
    from sqlalchemy import select

    from app.database.models import ExecutionMetricRow, SessionLocal

    with SessionLocal() as s:
        rows = s.scalars(select(ExecutionMetricRow).where(ExecutionMetricRow.source == "live")).all()
    return pd.DataFrame([{
        "workflow_id": r.workflow_id, "task_id": r.task_id, "agent_id": r.agent_id, "task_category": r.task_category,
        "task_priority": r.task_priority, "task_complexity": r.task_complexity, "dependency_count": r.dependency_count,
        "estimated_duration": r.estimated_duration, "current_workload": r.current_workload,
        "deadline_slack": (r.deadline_s or 0) / max(1e-6, (r.task_complexity or 1) * settings.task_deadline_s_per_complexity / 2.5),
        "task_failed": int(bool(r.task_failed)), "deadline_missed": int(bool(r.deadline_missed)), "source": "live"} for r in rows])


def prepare_failure_dataset(source: str = "synthetic", n_workflows: int = 800, seed: int = 42) -> pd.DataFrame:
    """source: synthetic | live | both. Validates the schema and fills missing inputs."""
    parts = []
    if source in ("synthetic", "both"):
        parts.append(_simulate(n_workflows, seed))
    if source in ("live", "both"):
        live = _live_rows()
        if not live.empty:
            parts.append(live)
    if not parts:
        raise ValueError("no execution history available for source=" + source)
    df = pd.concat(parts, ignore_index=True)
    missing = [c for c in ["workflow_id", *FEATURES, *TARGETS] if c not in df.columns]
    if missing:
        raise ValueError(f"execution history missing columns: {missing}")
    return _fill(df)


def _fill(df: pd.DataFrame) -> pd.DataFrame:
    df = df.copy()
    defaults = {"task_category": "development", "task_priority": "medium", "agent_id": "unknown", "task_complexity": 3,
                "dependency_count": 0, "estimated_duration": 7.5, "current_workload": 0, "deadline_slack": 1.5}
    for c, v in defaults.items():
        if c not in df:
            df[c] = v
        df[c] = df[c].fillna(v)
    return df


# ------------------------------------------------------------------ models
def _pre(scale: bool) -> ColumnTransformer:
    num = StandardScaler() if scale else "passthrough"
    return ColumnTransformer([("cat", OneHotEncoder(handle_unknown="ignore", sparse_output=False), CATEGORICAL), ("num", num, NUMERIC)])


def _candidates() -> dict:
    c = {
        "dummy_prior": (Pipeline([("pre", _pre(False)), ("clf", DummyClassifier(strategy="prior"))]), {}),
        "logistic_regression": (Pipeline([("pre", _pre(True)), ("clf", LogisticRegression(max_iter=2000))]), {"clf__C": [0.1, 1.0, 10.0]}),
        "random_forest": (Pipeline([("pre", _pre(False)), ("clf", RandomForestClassifier(random_state=42, n_jobs=1))]),
                          {"clf__n_estimators": [300], "clf__max_depth": [6, 12], "clf__min_samples_leaf": [5, 20]}),
    }
    if XGBClassifier is not None:
        c["xgboost"] = (Pipeline([("pre", _pre(False)), ("clf", XGBClassifier(n_estimators=300, eval_metric="logloss", random_state=42, n_jobs=1))]),
                        {"clf__max_depth": [3, 5], "clf__learning_rate": [0.05, 0.1]})
    return c


def _metrics(y, p, thr) -> dict:
    pred = (p >= thr).astype(int)
    tn, fp, fn, tp = confusion_matrix(y, pred, labels=[0, 1]).ravel()
    return {"pr_auc": round(float(average_precision_score(y, p)), 4), "precision": round(float(precision_score(y, pred, zero_division=0)), 4),
            "recall": round(float(recall_score(y, pred, zero_division=0)), 4), "f1": round(float(f1_score(y, pred, zero_division=0)), 4),
            "brier": round(float(brier_score_loss(y, p)), 4), "false_positive_rate": round(float(fp / max(1, fp + tn)), 4),
            "threshold": round(float(thr), 3), "confusion_matrix": [[int(tn), int(fp)], [int(fn), int(tp)]],
            "positive_rate": round(float(np.mean(y)), 4)}


def train_failure_model(df: pd.DataFrame | None = None, seed: int = 42) -> dict:
    df = df if df is not None else prepare_failure_dataset()
    assert_no_leakage(FEATURES)
    gss = GroupShuffleSplit(n_splits=1, test_size=0.2, random_state=seed)
    tr_idx, te_idx = next(gss.split(df, groups=df["workflow_id"]))
    tr, te = df.iloc[tr_idx], df.iloc[te_idx]
    gss2 = GroupShuffleSplit(n_splits=1, test_size=0.2, random_state=seed + 1)
    fit_idx, val_idx = next(gss2.split(tr, groups=tr["workflow_id"]))
    fit, val = tr.iloc[fit_idx], tr.iloc[val_idx]
    bundle = {"features": FEATURES, "version": f"failure-v1-{int(time.time())}", "data_source": sorted(df["source"].unique().tolist()), "targets": {}}
    report = {"data": "SYNTHETIC execution history" if set(df["source"]) == {"synthetic"} else f"sources: {sorted(df['source'].unique())}",
              "rows": int(len(df)), "workflows": int(df["workflow_id"].nunique()), "split": "GroupShuffleSplit by workflow (train/val/test)",
              "features": FEATURES, "excluded_post_execution": sorted(POST_EXECUTION), "targets": {}}
    for target in TARGETS:
        res, best_name, best_est, best_ap = {}, None, None, -1.0
        for name, (pipe, grid) in _candidates().items():
            t0 = time.time()
            if grid:
                gs = GridSearchCV(pipe, grid, cv=GroupKFold(n_splits=3), scoring="average_precision", n_jobs=-1)
                gs.fit(fit[FEATURES], fit[target], groups=fit["workflow_id"])
                est, params = gs.best_estimator_, {k.replace("clf__", ""): v for k, v in gs.best_params_.items()}
            else:
                est, params = pipe.fit(fit[FEATURES], fit[target]), {}
            ap = average_precision_score(val[target], est.predict_proba(val[FEATURES])[:, 1])
            res[name] = {"val_pr_auc": round(float(ap), 4), "best_params": params, "fit_seconds": round(time.time() - t0, 2)}
            if name != "dummy_prior" and ap > best_ap:
                best_name, best_est, best_ap = name, est, ap
        # calibrate the selected model on the validation workflows (prefit), keep the base model for SHAP
        try:
            from sklearn.frozen import FrozenEstimator

            cal = CalibratedClassifierCV(FrozenEstimator(best_est), method="sigmoid").fit(val[FEATURES], val[target])
        except ImportError:  # older scikit-learn
            cal = CalibratedClassifierCV(best_est, method="sigmoid", cv="prefit").fit(val[FEATURES], val[target])
        pv = cal.predict_proba(val[FEATURES])[:, 1]
        prec, rec, thr = precision_recall_curve(val[target], pv)
        f1s = 2 * prec * rec / np.clip(prec + rec, 1e-9, None)
        threshold = float(thr[int(np.argmax(f1s[:-1]))]) if len(thr) else 0.5
        p_cal = cal.predict_proba(te[FEATURES])[:, 1]
        p_raw = best_est.predict_proba(te[FEATURES])[:, 1]
        dummy = _candidates()["dummy_prior"][0].fit(tr[FEATURES], tr[target]).predict_proba(te[FEATURES])[:, 1]
        report["targets"][target] = {
            "candidates": res, "selected": best_name, "threshold_selected_on": "validation (max F1)",
            "test_calibrated": _metrics(te[target].values, p_cal, threshold),
            "test_uncalibrated_brier": round(float(brier_score_loss(te[target], p_raw)), 4),
            "test_dummy": _metrics(te[target].values, dummy, 0.5),
            "n_train": int(len(fit)), "n_val": int(len(val)), "n_test": int(len(te)),
        }
        bundle["targets"][target] = {"calibrated": cal, "base": best_est, "model": best_name, "threshold": threshold}
    joblib.dump(bundle, MODEL_PATH)
    METRICS_PATH.write_text(json.dumps(report, indent=2), encoding="utf-8")
    load_bundle.cache_clear()
    return report


def evaluate_failure_model(df: pd.DataFrame, bundle: dict | None = None) -> dict:
    bundle = bundle or load_bundle()
    if bundle is None:
        raise FileNotFoundError("failure model not trained; run `python scripts/evaluate_enhancements.py --only risk`")
    df = _fill(df)
    out = {}
    for target, b in bundle["targets"].items():
        if target in df:
            out[target] = _metrics(df[target].values, b["calibrated"].predict_proba(df[FEATURES])[:, 1], b["threshold"])
    return out


# ------------------------------------------------------------------ inference
@lru_cache(maxsize=1)
def load_bundle():
    return joblib.load(MODEL_PATH) if MODEL_PATH.exists() else None


def _frame(records: list[dict]) -> pd.DataFrame:
    assert_no_leakage(set(FEATURES))
    return _fill(pd.DataFrame([{k: r.get(k) for k in FEATURES} for r in records]))


def _predict(records: list[dict], target: str) -> list[float]:
    b = load_bundle()
    if b is None:
        raise FileNotFoundError("failure model not trained; run `python scripts/evaluate_enhancements.py --only risk`")
    return [round(float(p), 4) for p in b["targets"][target]["calibrated"].predict_proba(_frame(records))[:, 1]]


def predict_failure_probability(records: list[dict]) -> list[float]:
    return _predict(records, "task_failed")


def predict_deadline_risk(records: list[dict]) -> list[float]:
    return _predict(records, "deadline_missed")


def risk_category(p: float) -> str:
    if p >= settings.risk_high_threshold:
        return "High"
    if p >= settings.risk_medium_threshold:
        return "Medium"
    return "Low"


_READABLE = {"task_complexity": "task complexity", "current_workload": "agent's current workload", "dependency_count": "number of prerequisites",
             "estimated_duration": "estimated duration", "deadline_slack": "deadline slack", "task_category": "task category",
             "task_priority": "priority", "agent_id": "assigned agent"}


def explain_risk_prediction(record: dict, target: str = "task_failed", top_n: int = 4) -> dict:
    """Feature contributions for one task: SHAP for tree models, coefficient x standardised value for
    logistic regression. Contributions explain the base model's score (before calibration)."""
    b = load_bundle()
    if b is None:
        raise FileNotFoundError("failure model not trained")
    t = b["targets"][target]
    pipe = t["base"]
    X = _frame([record])
    pre, clf = pipe.named_steps["pre"], pipe.named_steps["clf"]
    Z = pre.transform(X)
    names = list(pre.get_feature_names_out())
    method = "shap"
    if t["model"] in ("random_forest", "xgboost"):
        import shap

        sv = shap.TreeExplainer(clf).shap_values(Z)
        sv = np.asarray(sv[1] if isinstance(sv, list) else sv)
        contrib = sv[0, :, 1] if sv.ndim == 3 else sv[0]
    else:
        method = "linear_coefficients"
        contrib = (np.asarray(Z)[0] * clf.coef_[0])
    agg: dict[str, float] = {}
    for n, c in zip(names, contrib):
        base = n.split("__", 1)[1]
        key = next((f for f in FEATURES if base == f or base.startswith(f + "_")), base)
        agg[key] = agg.get(key, 0.0) + float(c)
    top = sorted(agg.items(), key=lambda kv: -abs(kv[1]))[:top_n]
    p = _predict([record], target)[0]
    up = [f"{_READABLE.get(k, k)} ({record.get(k)})" for k, v in top if v > 0]
    down = [f"{_READABLE.get(k, k)} ({record.get(k)})" for k, v in top if v < 0]
    text = f"{risk_category(p)} risk ({p:.0%} calibrated probability of {'failure' if target == 'task_failed' else 'missing the deadline'})."
    if up:
        text += " Raised by " + ", ".join(up) + "."
    if down:
        text += " Lowered by " + ", ".join(down) + "."
    return {"probability": p, "category": risk_category(p), "method": method, "model": t["model"],
            "factors": [{"feature": k, "contribution": round(v, 4), "value": record.get(k)} for k, v in top], "explanation": text}
